import{_ as p,a0 as l,w as o,s as r,I as a,x as n,a1 as e,A as t,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"迁移到 Linux：磁盘、文件、和文件系统 | LCTT x X-CMD","titleTemplate":false,"description":"迁移到 Linux：磁盘、文件、和文件系统 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"迁移到 Linux：磁盘、文件、和文件系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"迁移到 Linux：磁盘、文件、和文件系统 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171127 Migrating to Linux Disks Files and Filesystems","title":"迁移到 Linux：磁盘、文件、和文件系统","tag":"201801","desc":""},"relativePath":"201801/20171127 Migrating to Linux Disks Files and Filesystems.md","filePath":"[post].md"}'),u={name:"201801/20171127 Migrating to Linux Disks Files and Filesystems.md"};function x(c,s,g,m,b,h){const i=l("Link");return o(),r("div",null,[s[16]||(s[16]=a("h1",{id:"迁移到-linux-磁盘、文件、和文件系统",tabindex:"-1"},[n("迁移到 Linux：磁盘、文件、和文件系统 "),a("a",{class:"header-anchor",href:"#迁移到-linux-磁盘、文件、和文件系统","aria-label":"Permalink to “迁移到 Linux：磁盘、文件、和文件系统”"},"​")],-1)),s[17]||(s[17]=a("p",null,[a("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/butterflies-807551_1920.jpg?itok=pxTxwvFO",alt:"Migrating to LInux ",title:"Migrating to LInux "})],-1)),s[18]||(s[18]=a("blockquote",null,[a("p",null,"在你的主要桌面计算机上安装和使用 Linux 将帮你快速熟悉你需要的工具和方法。")],-1)),a("p",null,[s[1]||(s[1]=n("这是我们的迁移到 Linux 系列文章的第二篇。如果你错过了第一篇，",-1)),e(i,{href:"https://linux.cn/article-9212-1.html"},{default:t(()=>[...s[0]||(s[0]=[n("你可以在这里找到它",-1)])]),_:1}),s[2]||(s[2]=n("。就如之前提到过的，为什么要迁移到 Linux 的有几个原因。你可以在你的工作中为 Linux 开发和使用代码，或者，你可能只是想去尝试一下新事物。",-1))]),s[19]||(s[19]=d(`<p>不论是什么原因，在你主要使用的桌面计算机上拥有一个 Linux，将帮助你快速熟悉你需要的工具和方法。在这篇文章中，我将介绍 Linux 的文件、文件系统和磁盘。</p><h3 id="我的-c-在哪里" tabindex="-1">我的 C:\\ 在哪里？ <a class="header-anchor" href="#我的-c-在哪里" aria-label="Permalink to “我的 C:\\ 在哪里？”">​</a></h3><p>如果你是一个 Mac 用户，Linux 对你来说应该非常熟悉，Mac 使用的文件、文件系统、和磁盘与 Linux 是非常接近的。另一方面，如果你的使用经验主要是 Windows，访问 Linux 下的磁盘可能看上去有点困惑。一般，Windows 给每个磁盘分配一个盘符（像 C:\\）。而 Linux 并不是这样。而在你的 Linux 系统中它是一个单一的文件和目录的层次结构。</p><p>让我们看一个示例。假设你的计算机使用了一个主硬盘、一个有 <code>Books</code> 和 <code>Videos</code> 目录的 CD-ROM 、和一个有 <code>Transfer</code> 目录的 U 盘，在你的 WIndows 下，你应该看到的是下面的样子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\  [硬盘]</span></span>
<span class="line"><span>├ System</span></span>
<span class="line"><span>├ System32</span></span>
<span class="line"><span>├ Program Files</span></span>
<span class="line"><span>├ Program Files (x86)</span></span>
<span class="line"><span>└ &lt;更多目录&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>D:\\ [CD-ROM]</span></span>
<span class="line"><span>├ Books</span></span>
<span class="line"><span>└ Videos</span></span>
<span class="line"><span></span></span>
<span class="line"><span>E:\\ [U 盘]</span></span>
<span class="line"><span>└ Transfer</span></span></code></pre></div><p>而一个典型的 Linux 系统却是这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ (最顶级的目录，称为根目录) [硬盘]</span></span>
<span class="line"><span>├ bin</span></span>
<span class="line"><span>├ etc</span></span>
<span class="line"><span>├ lib</span></span>
<span class="line"><span>├ sbin</span></span>
<span class="line"><span>├ usr</span></span>
<span class="line"><span>├ &lt;更多目录&gt;</span></span>
<span class="line"><span>└ media</span></span>
<span class="line"><span>   └ &lt;你的用户名&gt;</span></span>
<span class="line"><span>       ├ cdrom  [CD-ROM]</span></span>
<span class="line"><span>       │  ├ Books</span></span>
<span class="line"><span>       │  └ Videos</span></span>
<span class="line"><span>       └ Kingme_USB [U 盘]</span></span>
<span class="line"><span>           └ Transfer</span></span></code></pre></div><p>如果你使用一个图形化环境，通常，Linux 中的文件管理器将出现看起来像驱动器的图标的 CD-ROM 和 USB 便携式驱动器，因此，你根本就无需知道介质所在的目录。</p><h3 id="文件系统" tabindex="-1">文件系统 <a class="header-anchor" href="#文件系统" aria-label="Permalink to “文件系统”">​</a></h3><p>Linux 称这些东西为文件系统。文件系统是在介质（比如，硬盘）上保持跟踪所有的文件和目录的一组结构。如果没有用于存储数据的文件系统，我们所有的信息就会混乱，我们就不知道哪个块属于哪个文件。你可能听到过一些类似 ext4、XFS 和 Btrfs 之类的名字，这些都是 Linux 文件系统。</p><p>每种保存有文件和目录的介质都有一个文件系统在上面。不同的介质类型可能使用了为它优化过的特定的文件系统。比如，CD-ROM 使用 ISO9660 或者 UDF 文件系统类型。USB 便携式驱动器一般使用 FAT32，以便于它们可以很容易去与其它计算机系统共享。</p><p>Windows 也使用文件系统。不过，我们不会过多的讨论它。例如，当你插入一个 CD-ROM，Windows 将读取 ISO9660 文件系统结构，分配一个盘符给它，然后，在盘符（比如，D:\\）下显示文件和目录。当然，如果你深究细节，从技术角度说，Windows 是分配一个盘符给一个文件系统，而不是整个驱动器。</p><p>使用同样的例子，Linux 也读取 ISO9660 文件系统结构，但它不分配盘符，它附加文件系统到一个目录（这个过程被称为<ruby>挂载<rt>mount</rt></ruby>）。Linux 将随后在所挂载的目录（比如是， <code>/media/&lt;your user name&gt;/cdrom</code> ）下显示 CD-ROM 上的文件和目录。</p><p>因此，在 Linux 上回答 “我的 C:\\ 在哪里？” 这个问题，答案是，这里没有 C:\\，它们工作方式不一样。</p><h3 id="文件" tabindex="-1">文件 <a class="header-anchor" href="#文件" aria-label="Permalink to “文件”">​</a></h3><p>Windows 将文件和目录（也被称为文件夹）存储在它的文件系统中。但是，Linux 也让你将其它的东西放到文件系统中。这些其它类型的东西是文件系统的原生的对象，并且，它们和普通文件实际上是不同的。除普通文件和目录之外，Linux 还允许你去创建和使用<ruby>硬链接<rt>hard link</rt></ruby>、<ruby>符号链接<rt>symbolic link</rt></ruby>、<ruby>命名管道<rt>named pipe</rt></ruby>、<ruby>设备节点<rt>device node</rt></ruby>、和<ruby>套接字<rt>socket</rt></ruby>。在这里，我们不展开讨论所有的文件系统对象的类型，但是，这里有几种经常使用到的需要知道。</p><p>硬链接用于为文件创建一个或者多个别名。指向磁盘上同样内容的每个别名的名字是不同的。如果在一个文件名下编辑文件，这个改变也同时出现在其它的文件名上。例如，你有一个 <code>MyResume_2017.doc</code>，它还有一个被称为 <code>JaneDoeResume.doc</code> 的硬链接。（注意，硬链接是从命令行下，使用 <code>ln</code> 的命令去创建的）。你可以找到并编辑 <code>MyResume_2017.doc</code>，然后，然后找到 <code>JaneDoeResume.doc</code>，你发现它保持了跟踪 —— 它包含了你所有的更新。</p><p>符号链接有点像 Windows 中的快捷方式。文件系统的入口包含一个到其它文件或者目录的路径。在很多方面，它们的工作方式和硬链接很相似，它们可以创建一个到其它文件的别名。但是，符号链接也可以像文件一样给目录创建一个别名，并且，符号链接可以指向到不同介质上的不同文件系统，而硬链接做不到这些。（注意，你可以使用带 <code>-s</code> 选项的 <code>ln</code> 命令去创建一个符号链接）</p><h3 id="权限" tabindex="-1">权限 <a class="header-anchor" href="#权限" aria-label="Permalink to “权限”">​</a></h3><p>Windows 和 Linux 另一个很大的区别是涉及到文件系统对象（文件、目录、及其它）的权限。Windows 在文件和目录上实现了一套非常复杂的权限。例如，用户和用户组可以有权限去读取、写入、运行、修改等等。用户和用户组可以授权访问除例外以外的目录中的所有内容，也可以不允许访问除例外的目录中的所有内容。</p><p>然而，大多数使用 Windows 的人并不会去使用特定的权限；因此，当他们发现在 Linux 上是强制使用一套默认权限时，他们感到非常惊讶！Linux 通过使用 SELinux 或者 AppArmor 可以强制执行一套更复杂的权限。但是，大多数 Linux 安装版都只是使用了内置的默认权限。</p><p>在默认的权限中，文件系统中的每个条目都有一套为它的文件所有者、文件所在的组、和其它人的设置的权限。这些权限允许他们：读取、写入和运行。给它们的权限是有层次继承的。首先，它检查这个（登入的）用户是否为该文件所有者和拥有的权限。如果不是，然后检查这个用户是否在文件所在的组中和该组拥有的权限。如果不是，然后它再检查其它人拥有的权限。这里设置了其它人的权限。但是，这里设置的三套权限大多数情况下都会使用其中的一套。</p><p>如果你使用命令行，你输入 <code>ls -l</code>，你可以看到如下所表示的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rwxrw-r-- 1 stan dndgrp 25 Oct 33rd 25:01 rolldice.sh</span></span></code></pre></div><p>最前面的字母，<code>rwxrw-r--</code>，展示了权限。在这个例子中，所有者（stan）可以读取、写入和运行这个文件（前面的三个字母，<code>rwx</code>）；dndgrp 组的成员可以读取和写入这个文件，但是不能运行（第二组的三个字母，<code>rw-</code>）；其它人仅可以读取这个文件（最后的三个字母，<code>r--</code>）。</p><p>（注意，在 Windows 中去生成一个可运行的脚本，你生成的文件要有一个特定的扩展名，比如 <code>.bat</code>，而在 Linux 中，扩展名在操作系统中没有任何意义。而是需要去设置这个文件可运行的权限）</p><p>如果你收到一个 “permission denied” 错误，可能是你去尝试运行了一个要求管理员权限的程序或者命令，或者你去尝试访问一个你的帐户没有访问权限的文件。如果你尝试去做一些要求管理员权限的事，你必须切换登入到一个被称为 <code>root</code> 的用户帐户。或者通过在命令行使用一个被称为 <code>sudo</code> 的辅助程序。它可以临时允许你以 <code>root</code> 权限运行。当然，<code>sudo</code> 工具，也会要求你输入密码，以确保你真的有权限。</p><h3 id="硬盘文件系统" tabindex="-1">硬盘文件系统 <a class="header-anchor" href="#硬盘文件系统" aria-label="Permalink to “硬盘文件系统”">​</a></h3><p>Windows 主要使用一个被称为 NTFS 的硬盘文件系统。在 Linux 上，你也可以选一个你希望去使用的硬盘文件系统。不同的文件系统类型呈现不同的特性和不同的性能特征。现在主流的原生 Linux 的文件系统是 Ext4。但是，在安装 Linux 的时候，你也有丰富的文件系统类型可供选择，比如，Ext3（Ext4 的前任）、XFS、Btrfs、UBIFS（用于嵌入式系统）等等。如果你不确定要使用哪一个，Ext4 是一个很好的选择。</p><hr>`,30)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),e(i,{href:"https://www.linux.com/blog/learn/intro-to-linux/2017/11/migrating-linux-disks-files-and-filesystems"},{default:t(()=>[...s[3]||(s[3]=[n("https://www.linux.com/blog/learn/intro-to-linux/2017/11/migrating-linux-disks-files-and-filesystems",-1)])]),_:1})]),a("p",null,[s[8]||(s[8]=n("作者：",-1)),e(i,{href:"https://www.linux.com/users/johnbonesio"},{default:t(()=>[...s[5]||(s[5]=[n("JOHN BONESIO",-1)])]),_:1}),s[9]||(s[9]=n(" 译者：",-1)),e(i,{href:"https://github.com/qhwdw"},{default:t(()=>[...s[6]||(s[6]=[n("qhwdw",-1)])]),_:1}),s[10]||(s[10]=n(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[11]||(s[11]=[n("LCTT",-1)])]),_:1}),s[14]||(s[14]=n(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[12]||(s[12]=[n("Linux中国",-1)])]),_:1}),s[15]||(s[15]=n(" 荣誉推出",-1))])])}const w=p(u,[["render",x]]);export{f as __pageData,w as default};
